<script setup lang="ts">
import { ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { actor, authError, login } from '../auth';
import { isMock } from '../api';
const router = useRouter(); const route = useRoute();
const username = ref(''); const password = ref(''); const busy = ref(false); const error = ref('');
async function signIn(demo?: string) { busy.value = true; error.value = ''; try { await login(demo || username.value, demo ? '' : password.value); const target = typeof route.query.redirect === 'string' && route.query.redirect.startsWith('/') && !route.query.redirect.startsWith('//') ? route.query.redirect : actor.value?.role === 'STUDENT' ? '/' : '/teacher/problems'; await router.replace(target); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><div class="login-page"><section class="login-story"><div class="brand"><span class="brand-mark">C</span><span>C 课堂<small>程序设计教学空间</small></span></div><div class="login-copy"><h1>C 语言<br>教学辅助系统</h1><p>课程作业、在线评测与学习指导</p></div><small>C 语言教学辅助系统 · 课程实验平台</small></section><section class="login-form"><h2>账号登录</h2><p class="muted">{{ isMock ? '选择一个角色，体验教学与作答流程。' : '使用学校提供的账号登录。' }}</p><el-alert v-if="error || authError" :title="error || authError" type="error" show-icon :closable="false" /><template v-if="isMock"><div class="demo-notice"><strong>演示模式</strong><p>使用模拟数据，代码不实际运行，AI 内容为示例。刷新后部分记录会重置。</p></div><el-button type="primary" size="large" :loading="busy" @click="signIn('student')">学生演示</el-button><el-button size="large" :disabled="busy" @click="signIn('teacher')">教师演示</el-button><button class="text-button" :disabled="busy" @click="signIn('admin')">管理员演示</button></template><el-form v-else label-position="top" @submit.prevent="signIn()"><el-form-item label="账号"><el-input v-model="username" autocomplete="username" placeholder="输入账号" /></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" autocomplete="current-password" show-password placeholder="输入密码" /></el-form-item><el-button type="primary" native-type="submit" size="large" :loading="busy" :disabled="!username || !password">登录</el-button></el-form><p class="login-foot">{{ isMock ? '所有演示结果均有明确标识。' : '账号问题请联系课程教师或管理员。' }}</p></section></div></template>
